T={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)}
def transforms(s):
    outs=[]
    for ref in [False,True]:
      for k in range(4):
        pts=[]
        for y,x in s:
          if ref: x=-x
          for _ in range(k): y,x=x,-y
          pts.append((y,x))
        miny=min(y for y,x in pts); minx=min(x for y,x in pts)
        norm={(y-miny,x-minx) for y,x in pts}
        outs.append((ref,k,norm))
    return outs
[(a,b,c==T,c) for a,b,c in transforms(S)]

